ns.Data.OtherWeapons = {
  note = "Rogues start with Daggers and Thrown; Combat leveling wants a slow, high top-end main hand for Sinister Strike/Riposte; Assassination must use two daggers for Mutilate; Subtlety cares about weapon speed and swaps between a dagger (Backstab/Ambush) and a slow weapon (Sinister Strike), Hemorrhage (30) works with either. Hack and Slash (Combat row 5) replaces the four weapon specializations and adds an axe bonus.",
  rules = {
    {
      spec = "Assassination",
      rule = "Use two Daggers: Mutilate needs a dagger in both hands. Look for a high top-end dagger; it is generally worth dropping some stats for higher weapon damage. Before upgrading, double check the weapon is a Dagger.",
      source_url = "https://www.icy-veins.com/wow-forever/assassination-rogue-melee-dps-pve-stat-priority",
      checked = "2026-11-19",
    },
    {
      spec = "Combat",
      rule = "Main priority while leveling: a slow, high top-end main-hand weapon to maximise Riposte and Sinister Strike, then Agility and some Stamina.",
      source_url = "https://www.icy-veins.com/wow-forever/combat-rogue-leveling",
      checked = "2026-11-19",
    },
    {
      spec = "Combat",
      rule = "Hack and Slash combines the removed Dagger, Mace, Sword and Fist Weapon Specializations and adds a bonus for Axes: axes get the sword benefit (chance of an extra attack); maces ignore some armor instead of a stun chance. Icy Veins: Bloodslash Axe helps take advantage of Hack and Slash.",
      source_url = "https://news.blizzard.com/en-us/article/24310968/world-of-warcraft-forever-class-deep-dives-rogue-and-warlock",
      checked = "2026-11-19",
    },
    {
      spec = "Subtlety",
      rule = "Weapon speed matters: between a 15 DPS 1.9-speed weapon and a 14 DPS 2.8-speed weapon, the 2.8-speed one is better (many instant skills add a bonus on top of weapon damage). Avoid fast weapons such as Sword of Omen unless only in the off hand.",
      source_url = "https://www.icy-veins.com/wow-forever/subtlety-rogue-leveling",
      checked = "2026-11-19",
    },
    {
      spec = "Subtlety",
      rule = "Backstab/Ambush need a dagger in the main hand; Icy Veins gives weapon-swap macros (dagger for Ambush, slow weapon for Sinister Strike; a swap costs a GCD and resets the swing timer). Hemorrhage (30) deals the same damage with daggers or slow weapons.",
      source_url = "https://www.icy-veins.com/wow-forever/subtlety-rogue-leveling",
      checked = "2026-11-19",
    },
    {
